"""Caption / post-text extraction from yt-dlp metadata.

Rules:
* Text is copied exactly as yt-dlp returns it: Unicode, emoji, punctuation and line
  breaks are preserved. Nothing is trimmed, summarized, translated or generated.
* `caption` is only ever real text the creator wrote. When the platform gives us nothing,
  `caption` is None and the UI shows "Caption unavailable".
* Some titles are *generated by yt-dlp* (e.g. X/Twitter titles are "<name> - <first
  words of the post>", Instagram titles are "Video by <user>"). Those are flagged with
  `title_is_generated` and never used as the caption.
"""
from __future__ import annotations

import re
from typing import Any

from .platforms import platform_from_extractor

# Platforms where yt-dlp's `description` field is the creator's post text.
_DESCRIPTION_IS_POST_TEXT = {"twitter", "instagram", "tiktok", "facebook"}
# Platforms whose yt-dlp title is synthesized rather than written by the creator.
_GENERATED_TITLE = {"twitter", "instagram"}

# A hashtag starts with # not preceded by a word character, and continues over letters,
# digits, underscores, combining marks and joiners in any script.
_HASHTAG_RE = re.compile(r"(?<![\w&#])#([^\W_][\w‌‍·]*|_[\w‌‍·]+)", re.UNICODE)


def _clean(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    return value if value.strip() else None


def extract_hashtags(*texts: str | None) -> list[str]:
    seen: dict[str, str] = {}
    for text in texts:
        if not text:
            continue
        for match in _HASHTAG_RE.finditer(text):
            tag = match.group(1)
            if tag.isdigit():
                continue
            seen.setdefault(tag.casefold(), "#" + tag)
    return list(seen.values())


def extract_caption(info: dict[str, Any]) -> dict[str, Any]:
    platform = platform_from_extractor(info.get("extractor_key") or info.get("extractor"))
    title = _clean(info.get("title"))
    description = _clean(info.get("description"))
    title_is_generated = platform in _GENERATED_TITLE

    caption: str | None = None
    source: str | None = None
    if platform in _DESCRIPTION_IS_POST_TEXT:
        if description:
            caption, source = description, "post_text"
    elif platform == "reddit":
        # A Reddit post's title is the text the poster wrote; selftext (if any) is the description.
        if title:
            caption, source = title, "post_title"
    elif platform == "youtube":
        if description:
            caption, source = description, "video_description"
        elif title:
            caption, source = title, "video_title"
    else:
        if description:
            caption, source = description, "description"
        elif title and not title_is_generated:
            caption, source = title, "title"

    hashtags = extract_hashtags(caption, description if description is not caption else None)

    creator = {
        "name": _clean(info.get("uploader")) or _clean(info.get("channel")) or _clean(info.get("creator")),
        "handle": _clean(info.get("uploader_id")) or _clean(info.get("channel_id")),
        "url": _clean(info.get("uploader_url")) or _clean(info.get("channel_url")),
    }
    return {
        "platform": platform,
        "caption": caption,
        "caption_source": source,
        "caption_available": caption is not None,
        "title": title,
        "title_is_generated": title_is_generated,
        "description": description,
        "hashtags": hashtags,
        "tags": [t for t in (info.get("tags") or []) if isinstance(t, str)][:50],
        "creator": creator,
    }
